class StatsReporter
  def initialize(cloudwatch_client, environment)
    @client = cloudwatch_client
    @environment = environment
  end

  def report_quarter_hourly
    report_metric('JobsCount', GoodJob::Job.count - GoodJob::Job.succeeded.count)
    report_metric('FailedJobsCount', GoodJob::Job.where.not(error: nil).count)
    report_metric('StuckJobsCount', GoodJob::Job.where(finished_at: nil).where("COALESCE(scheduled_at, created_at) < ?", 1.hour.ago).count)
  end

  private
  def report_metric(name, value)
    @client.put_metric_data(
      namespace: 'NavodyDigital',
      metric_data: [
        {
          metric_name: name,
          dimensions: [{ name: 'Environment', value: @environment }],
          timestamp: Time.current.utc,
          value: value,
        }
      ]
    )
  end
end

class PagesController < ApplicationController
  def index
    @metadata.og.title = 'Návody.Digital: Jednoduché návody na slovenské úrady'
    @metadata.og.description = 'Interaktívne návody, ako vybaviť úradné záležitosti elektronicky.'

    @faqs = Page.faq.order(position: :asc).all
    @categories = Category.featured.order(featured_position: :asc, name: :asc)
    @documents = Document.featured.includes(:searchable).order(featured_position: :asc).map(&:searchable).compact # we do not have FK constraints here, compact eliminates any possible documents hanging without searchable counterpart, which was deleted
  end

  def show
    @page = Page.find_by_slug!(params[:id])

    @metadata.og.image = @page.image_name.presence || "placeholder.png"
  end
end

(function() {
  var isIFrame = window.parent !== window;
  if (!isIFrame) return;

  document.body.classList.add("body__iframe");

  var lastPageheight = null;
  function calculatePageHeight() {
    var content = document.querySelector(".navody-template__content");
    var height = content.clientHeight;

    if (lastPageheight !== height) {
      lastPageheight = height;
      window.parent.postMessage({ height, __NAVODY: true }, "*");
    }
  }

  const observer = new MutationObserver(calculatePageHeight);
  observer.observe(document.querySelector("body"), {
    attributes: true,
    childList: true,
    subtree: true
  });
  calculatePageHeight();
})();

