const configPaths = require('../config/paths.json')

const childDirectories = dir => {
  return fs.readdirSync(dir)
    .filter(file => fs.statSync(path.join(dir, file)).isDirectory())
}
const sdnChildDirectories = dir => {
  return fs.readdirSync(dir)
