package com.archimetes.cgpcon.websso;

import com.onelogin.saml2.settings.Saml2Settings;
import com.onelogin.saml2.settings.SettingsBuilder;

import java.io.FileInputStream;
import java.io.IOException;
import java.util.Properties;

public class Settings {

    public static Saml2Settings loadSettings() throws IOException {
        Properties conf = new Properties();
        conf.load(new FileInputStream(System.getProperty("catalina.base") + "/conf/webssodemo.saml.properties"));
        return new SettingsBuilder().fromProperties(conf).build();
    }

}

public record SamlConfig(ServiceProviderConfig ServiceProvider, IdentityProviderConfig IdentityProvider);
public record ServiceProviderConfig(string Id, CertificateConfig Certificate);
public record CertificateConfig(string Path, string Key);
public record IdentityProviderConfig(string Id, string MetadataLocation);

package com.archimetes.cgpcon.websso;

import com.onelogin.saml2.Auth;
import com.onelogin.saml2.exception.SettingsException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.servlet.ServletException;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;

public class LoginServlet extends HttpServlet {
    private static final Logger logger = LoggerFactory.getLogger(new Object() {}.getClass().getEnclosingClass());

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        try {
            Auth auth = new Auth( Settings.loadSettings() , request, response);
            String redir = request.getParameter("redir");
            if (redir == null) {
                auth.login();
            } else {
                auth.login(redir);
            }
        } catch (SettingsException ex) {
            logger.error("Exception caught", ex);
        }
    }
}

